input.command:
node -e "
const s1 = \"Cobalt Labs payments platform exits beta with four billion dollars in transaction volume. Cobalt Labs announced general availability of its payments platform after a six-month beta. The company says it processed four billion dollars in volume during beta with partners including Stripe. Top ten stories on HN this week includes one Cobalt Labs Show HN that hit number one. Daily Update on platform fees mentions Cobalt Labs and Stripe in the third paragraph.\";
const s2 = \"Your one o'clock Maya call overlaps with the customer interview at one fifteen. Quick call with Maya. Family call — Mom's birthday planning. Maya wants a quick call at one pm to lock in Mom's surprise birthday plans for next weekend. She already booked the restaurant tentatively.\";
const s3 = \"PSD3 final text dropped overnight — please read before three pm sync. The EU published the final PSD3 text overnight. Material changes to SCA exemption thresholds and a new fraud-data-sharing requirement that affects our checkout flow. Rahul has annotated the key sections. Implementation deadline is twenty twenty-seven.\";
const s4 = \"ACTION REQUIRED: credential rotation by May twentieth. Plaid is requiring all partners to rotate API credentials by May twentieth. After that date, unrotated keys will be revoked. Infra is CC'd but Jordan is the listed owner.\";
const text = [s1,s2,s3,s4].join('\\n\\n');
const words = text.match(/[A-Za-z]+(?:'[A-Za-z]+)?/g);
const wc = words?.length ?? 0;
const dur = Math.round((wc/155)*60);
const bad = /[\$%]|\\b\\d+([,.]\\d+)?\\b/.test(text);
console.log({wc, dur, bad});
"
